// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.bitwise;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.math.BigInteger;
import java.util.List;
import java.util.stream.Stream;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.base.CoreDatatype;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.Function;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

/**
 * Edge cases of the {@code bitf:} functions: two's complement semantics, arbitrary precision, shift distances and
 * accepted integer datatypes.
 */
class BitwiseFunctionsEdgeCaseTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	private static final BigInteger TWO_POW_64 = BigInteger.TWO.pow(64);
	private static final BigInteger TWO_POW_100 = BigInteger.TWO.pow(100);

	private static Literal integer(long v) {
		return VF.createLiteral(BigInteger.valueOf(v));
	}

	private static Literal integer(BigInteger v) {
		return VF.createLiteral(v);
	}

	private static Literal typed(String lexical, CoreDatatype.XSD datatype) {
		return VF.createLiteral(lexical, datatype);
	}

	@Test
	void negativeOperandsUseTwosComplement() {
		assertThat(new BitAnd().evaluate(VF, integer(-1), integer(255))).isEqualTo(integer(255));
		assertThat(new BitOr().evaluate(VF, integer(-2), integer(1))).isEqualTo(integer(-1));
		assertThat(new BitXor().evaluate(VF, integer(-1), integer(-1))).isEqualTo(integer(0));
		assertThat(new BitAnd().evaluate(VF, integer(-256), integer(255))).isEqualTo(integer(0));
		assertThat(new BitXor().evaluate(VF, integer(-1), integer(0))).isEqualTo(integer(-1));
		assertThat(new BitOr().evaluate(VF, integer(-8), integer(7))).isEqualTo(integer(-1));
	}

	@Test
	void operandsBeyond64BitsAreExact() {
		assertThat(new BitAnd().evaluate(VF, integer(TWO_POW_100.add(BigInteger.ONE)), integer(TWO_POW_100)))
				.isEqualTo(integer(TWO_POW_100));
		assertThat(new BitOr().evaluate(VF, integer(TWO_POW_100), integer(1)))
				.isEqualTo(integer(TWO_POW_100.add(BigInteger.ONE)));
		assertThat(new BitXor().evaluate(VF, integer(TWO_POW_100), integer(TWO_POW_100))).isEqualTo(integer(0));
		// infinite leading ones of a negative number reach beyond 64 bits as well
		assertThat(new BitAnd().evaluate(VF, integer(-1), integer(TWO_POW_100))).isEqualTo(integer(TWO_POW_100));
		assertThat(new BitXor().evaluate(VF, integer(TWO_POW_100), integer(-1)))
				.isEqualTo(integer(TWO_POW_100.not()));
		assertThat(((Literal) new BitOr().evaluate(VF, integer(TWO_POW_100), integer(TWO_POW_64))).integerValue())
				.isEqualTo(TWO_POW_100.add(TWO_POW_64));
	}

	@Test
	void bitNot() {
		assertThat(new BitNot().evaluate(VF, integer(0))).isEqualTo(integer(-1));
		assertThat(new BitNot().evaluate(VF, integer(-1))).isEqualTo(integer(0));
		assertThat(new BitNot().evaluate(VF, integer(TWO_POW_64)))
				.isEqualTo(integer(TWO_POW_64.negate().subtract(BigInteger.ONE)));
		assertThat(new BitNot().evaluate(VF, integer(5))).isEqualTo(integer(-6));
		assertThat(new BitNot().evaluate(VF, integer(Long.MIN_VALUE))).isEqualTo(integer(Long.MAX_VALUE));
	}

	@Test
	void bitCount() {
		assertThat(new BitCount().evaluate(VF, integer(0))).isEqualTo(integer(0));
		assertThat(new BitCount().evaluate(VF, integer(-1))).isEqualTo(integer(64));
		assertThat(new BitCount().evaluate(VF, integer(Long.MIN_VALUE))).isEqualTo(integer(1));
		assertThat(new BitCount().evaluate(VF, integer(-2))).isEqualTo(integer(63));
		assertThat(new BitCount().evaluate(VF, integer(255))).isEqualTo(integer(8));
		assertThat(new BitCount().evaluate(VF, integer(TWO_POW_100.subtract(BigInteger.ONE)))).isEqualTo(integer(100));
		// a negative value below the 64-bit two's complement range has no defined bit count
		assertThatThrownBy(() -> new BitCount().evaluate(VF,
				integer(BigInteger.valueOf(Long.MIN_VALUE).subtract(BigInteger.ONE))))
						.isInstanceOf(ValueExprEvaluationException.class);
		// pins current behaviour: positive values are not limited to 64 bits
		assertThat(new BitCount().evaluate(VF, integer(TWO_POW_64))).isEqualTo(integer(1));
	}

	@Test
	void bitShiftLeft() {
		assertThat(new BitShiftLeft().evaluate(VF, integer(1), integer(64))).isEqualTo(integer(TWO_POW_64));
		assertThat(new BitShiftLeft().evaluate(VF, integer(5), integer(0))).isEqualTo(integer(5));
		assertThat(new BitShiftLeft().evaluate(VF, integer(-1), integer(3))).isEqualTo(integer(-8));
		// pins current behaviour: a negative distance shifts the other way (BigInteger semantics)
		assertThat(new BitShiftLeft().evaluate(VF, integer(8), integer(-2))).isEqualTo(integer(2));
		assertThat(new BitShiftLeft().evaluate(VF, integer(-8), integer(-2))).isEqualTo(integer(-2));
		// shift distances beyond the int range are errors
		assertThatThrownBy(() -> new BitShiftLeft().evaluate(VF, integer(1), integer(BigInteger.TWO.pow(40))))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new BitShiftLeft().evaluate(VF, integer(1), integer(Long.MAX_VALUE)))
				.isInstanceOf(ValueExprEvaluationException.class);
		assertThatThrownBy(() -> new BitShiftLeft().evaluate(VF, integer(1), integer(TWO_POW_100)))
				.isInstanceOf(ValueExprEvaluationException.class);
		// pins current behaviour: the distance must fit in 20 bits (so a result stays below one million bits)
		assertThatThrownBy(() -> new BitShiftLeft().evaluate(VF, integer(1), integer(1 << 20)))
				.isInstanceOf(ValueExprEvaluationException.class);
		Literal widest = (Literal) new BitShiftLeft().evaluate(VF, integer(1), integer((1 << 20) - 1));
		assertThat(widest.integerValue().bitLength()).isEqualTo(1 << 20);
	}

	@Test
	void bitShiftRightIsArithmetic() {
		assertThat(new BitShiftRight().evaluate(VF, integer(-1), integer(1))).isEqualTo(integer(-1));
		assertThat(new BitShiftRight().evaluate(VF, integer(-1), integer(100))).isEqualTo(integer(-1));
		assertThat(new BitShiftRight().evaluate(VF, integer(1), integer(100))).isEqualTo(integer(0));
		assertThat(new BitShiftRight().evaluate(VF, integer(-16), integer(2))).isEqualTo(integer(-4));
		assertThat(new BitShiftRight().evaluate(VF, integer(-5), integer(1))).isEqualTo(integer(-3));
		assertThat(new BitShiftRight().evaluate(VF, integer(5), integer(0))).isEqualTo(integer(5));
		assertThat(new BitShiftRight().evaluate(VF, integer(TWO_POW_100), integer(99))).isEqualTo(integer(2));
		// pins current behaviour: a negative distance shifts left
		assertThat(new BitShiftRight().evaluate(VF, integer(8), integer(-2))).isEqualTo(integer(32));
		assertThatThrownBy(() -> new BitShiftRight().evaluate(VF, integer(1), integer(BigInteger.TWO.pow(40))))
				.isInstanceOf(ValueExprEvaluationException.class);
	}

	static Stream<Function> functions() {
		return Stream.of(new BitAnd(), new BitOr(), new BitXor(), new BitNot(), new BitCount(), new BitShiftLeft(),
				new BitShiftRight());
	}

	private static Value[] args(Function function, Literal first, Literal second) {
		return function instanceof BitNot || function instanceof BitCount ? new Value[] { first }
				: new Value[] { first, second };
	}

	@ParameterizedTest
	@MethodSource("functions")
	void nonIntegerNumericDatatypesAreAnError(Function function) {
		for (Literal bad : List.of(typed("1.0", CoreDatatype.XSD.DECIMAL), VF.createLiteral(1.0),
				typed("1", CoreDatatype.XSD.FLOAT), typed("1", CoreDatatype.XSD.DOUBLE),
				typed("1.0", CoreDatatype.XSD.INTEGER))) {
			assertThatThrownBy(() -> function.evaluate(VF, args(function, bad, integer(1))))
					.as(function.getURI() + " " + bad)
					.isInstanceOf(ValueExprEvaluationException.class);
			if (args(function, integer(1), bad).length == 2) {
				assertThatThrownBy(() -> function.evaluate(VF, args(function, integer(1), bad)))
						.as(function.getURI() + " " + bad)
						.isInstanceOf(ValueExprEvaluationException.class);
			}
		}
	}

	@ParameterizedTest
	@MethodSource("functions")
	void derivedIntegerDatatypesAreAcceptedAndYieldXsdInteger(Function function) {
		for (Literal input : List.of(typed("5", CoreDatatype.XSD.LONG), typed("5", CoreDatatype.XSD.BYTE),
				typed("5", CoreDatatype.XSD.SHORT), typed("5", CoreDatatype.XSD.INT),
				typed("5", CoreDatatype.XSD.POSITIVE_INTEGER), typed("5", CoreDatatype.XSD.UNSIGNED_LONG),
				typed("18446744073709551615", CoreDatatype.XSD.UNSIGNED_LONG))) {
			Literal result = (Literal) function.evaluate(VF, args(function, input, typed("3", CoreDatatype.XSD.BYTE)));
			assertThat(result.getCoreDatatype()).as(function.getURI() + " " + input)
					.isEqualTo(CoreDatatype.XSD.INTEGER);
		}
		assertThat(new BitAnd().evaluate(VF, typed("12", CoreDatatype.XSD.LONG), typed("10", CoreDatatype.XSD.BYTE)))
				.isEqualTo(integer(8));
		assertThat(new BitNot().evaluate(VF, typed("-3", CoreDatatype.XSD.BYTE))).isEqualTo(integer(2));
	}
}
